var i=`0582-dogroma`;var n=`world-0582`;var o=`TM`;var a=`central-asia`;var r=4;var s=117;var m={en:`Dogroma`,ua:`Дограма`};var l={en:`A traditional dish from Turkmenistan, centered on lamb, yellow onion, pita bread. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туркменістан. Основні складники: ягнятина, жовта цибуля, піта. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 95 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 95 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:95,i:[[`lamb`,700,`g`],[`water`,1400,`ml`],[`yellow-onion`,200,`g`]]},{en:`Toast these ingredients over medium heat for about 7 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 7 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:7,i:[[`pita-bread`,5,`pcs`]]},{en:`Shred or tear the cooked components, then fold together with the listed additions.`,ua:`Нашаткуйте або розберіть готові компоненти на волокна й змішайте з зазначеними додатками.`,t:[`shredding`,`mixing`],m:7,i:[]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:8,i:[[`chicken-stock`,500,`ml`],[`ground-black-pepper`,null,`to_taste`]]}];var g={slug:i,id:n,country:`TM`,region:a,servings:4,minutes:117,title:m,text:l,steps:d};export{o as country,g as default,n as id,s as minutes,a as region,r as servings,i as slug,d as steps,l as text,m as title};